static void metadata(int fd,NSString *stage){struct stat st={0};int statResult=fstat(fd,&st);int available=-1;int ioctlResult=ioctl(fd,FIONREAD,&available);struct pollfd p={.fd=fd,.events=POLLIN};int pollResult=poll(&p,1,0);emit(@{@"event":@"fd",@"stage":stage,@"fd":@(fd),@"fstat_result":@(statResult),@"mode":@(st.st_mode),@"is_fifo":@(S_ISFIFO(st.st_mode)),@"device":@(st.st_dev),@"inode":@(st.st_ino),@"ioctl_result":@(ioctlResult),@"available_bytes":@(available),@"poll_result":@(pollResult),@"revents":@(p.revents),@"pollin":@((p.revents&POLLIN)!=0),@"pollhup":@((p.revents&POLLHUP)!=0)});}
static void scanout(SpiceDisplayChannel *channel,GParamSpec *spec,gpointer data){notifications++;const SpiceGlScanout *info=spice_display_channel_get_gl_scanout(channel);texture=nil;if(!info){emit(@{@"event":@"scanout-null"});return;}emit(@{@"event":@"scanout",@"number":@(notifications),@"width":@(info->width),@"height":@(info->height),@"y0top":@(info->y0top)});metadata(info->fd,@"before-read");if(!consume)return;struct pollfd p={.fd=info->fd,.events=POLLIN};int available=0;ioctl(info->fd,FIONREAD,&available);if(poll(&p,1,0)<=0||!(p.revents&POLLIN)||available<4){emit(@{@"event":@"no-readable-id"});return;}if(p.revents&POLLHUP){emit(@{@"event":@"stale-writer-closed"});return;}IOSurfaceID id=0;ssize_t n=read(info->fd,&id,sizeof(id));emit(@{@"event":@"read",@"bytes":@(n),@"errno":@(n<0?errno:0),@"surface_id":@(id)});metadata(info->fd,@"after-read");if(n!=sizeof(id))return;IOSurfaceRef surface=IOSurfaceLookup(id);if(!surface){emit(@{@"event":@"surface-unavailable"});return;}if(info->width!=IOSurfaceGetWidth(surface)||info->height!=IOSurfaceGetHeight(surface)||info->width>1920||info->height>1080||IOSurfaceGetPixelFormat(surface)!='BGRA'){CFRelease(surface);emit(@{@"event":@"unsupported-surface"});return;}MTLTextureDescriptor *desc=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:info->width height:info->height mipmapped:NO];desc.usage=MTLTextureUsageShaderRead;texture=[device newTextureWithDescriptor:desc iosurface:surface plane:0];CFRelease(surface);emit(@{@"event":@"bound-surface",@"valid":@(texture!=nil)});}
