static void channel(SpiceSession *session,SpiceChannel *ch,gpointer data){if(SPICE_IS_DISPLAY_CHANNEL(ch)){g_signal_connect(ch,"notify::gl-scanout",G_CALLBACK(scanout),NULL);g_signal_connect(ch,"gl-draw",G_CALLBACK(draw),NULL);spice_channel_connect(ch);}}
static gboolean timeout(gpointer data){g_main_loop_quit(loop);return G_SOURCE_REMOVE;}
int main(int argc,char **argv){@autoreleasepool{if(argc!=3)return 2;consume=strcmp(argv[2],"observe")!=0;device=MTLCreateSystemDefaultDevice();queue=[device newCommandQueue];if(!device||!queue)return 3;loop=g_main_loop_new(NULL,FALSE);SpiceSession *session=spice_session_new();g_object_set(session,"unix-path",argv[1],NULL);g_signal_connect(session,"channel-new",G_CALLBACK(channel),NULL);if(spice_session_connect(session)){g_timeout_add_seconds(5,timeout,NULL);g_main_loop_run(loop);}BOOL captured=captures==2&&hashes[0]!=hashes[1];emit(@{@"event":@"result",@"mode":consume?@"consume":@"observe",@"notifications":@(notifications),@"draws":@(draws),@"changing_frames_captured":@(captured),@"capture_count":@(captures)});spice_session_disconnect(session);g_object_unref(session);g_main_loop_unref(loop);return consume?(captured?0:1):(notifications&&draws?0:1);}}
